// Compare Timezones: static-page version of src/TimeComparison.jsx (no framework, no build step).
// Reads /data/timezones.json (generated by scripts/generate-tool-pages.mjs). Uses the same
// localStorage keys as the old React tool, so saved zones carry over.
(function () {
  'use strict';

  var LEGACY = { 'Asia/Calcutta': 'Asia/Kolkata' };
  var DEFAULT_ZONES = ['Europe/London', 'America/New_York', 'Asia/Singapore'];
  var $ = function (id) { return document.getElementById(id); };
  var norm = function (z) { return LEGACY[z] || z; };

  function read(key, fallback) {
    try { var v = localStorage.getItem(key); return v === null ? fallback : v; } catch (e) { return fallback; }
  }
  function write(key, val) { try { localStorage.setItem(key, val); } catch (e) { /* private mode */ } }

  var detected = norm((Intl.DateTimeFormat().resolvedOptions() || {}).timeZone || 'UTC');
  var primary = norm(read('primaryZone', '') || detected);
  var zones = [];
  try {
    var saved = JSON.parse(read('selectedZones', '[]'));
    if (Array.isArray(saved)) zones = saved.filter(function (z) { return typeof z === 'string' && z.trim(); }).map(norm);
  } catch (e) { zones = []; }
  if (!zones.length) zones = DEFAULT_ZONES.slice();
  var info = {}; // IANA name -> { city, country }
  var all = [];

  // ---- time maths (Intl only) ----
  function parts(ts, tz) {
    var p = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' }).formatToParts(new Date(ts));
    var v = {}; p.forEach(function (x) { v[x.type] = +x.value; });
    return v;
  }
  function offsetMs(tz, ts) {
    var v = parts(ts, tz);
    return Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second) - Math.floor(ts / 1000) * 1000;
  }
  function toUtc(y, mo, d, h, mi, tz) { // wall-clock in tz -> instant (two passes handles DST edges)
    var guess = Date.UTC(y, mo, d, h, mi);
    guess -= offsetMs(tz, guess);
    return new Date(Date.UTC(y, mo, d, h, mi) - offsetMs(tz, guess));
  }
  function fmtTime(d, tz) { return new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: true }).format(d); }
  function fmtDate(d, tz) { return new Intl.DateTimeFormat('en-GB', { timeZone: tz, day: '2-digit', month: 'short' }).format(d); }
  function ymd(d, tz) { return new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(d); }
  function gmt(tz, d) {
    var m = Math.round(offsetMs(tz, d.getTime()) / 60000), a = Math.abs(m);
    return 'GMT' + (m < 0 ? '-' : '+') + Math.floor(a / 60) + (a % 60 ? ':' + String(a % 60).padStart(2, '0') : '');
  }
  function label(tz) { var i = info[tz]; return i ? { city: i.city, country: i.country } : { city: tz.split('/').pop().replace(/_/g, ' '), country: '' }; }

  // ---- state ----
  function persist() { write('primaryZone', primary); write('selectedZones', JSON.stringify(zones)); }
  function ordered() { return [primary].concat(zones.filter(function (z) { return z !== primary; })); }

  function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }

  var nowCells = [];
  function render() {
    persist();
    var body = $('tc-rows'); body.textContent = ''; nowCells = [];
    var t = $('tc-time').value, dt = $('tc-date').value;
    var now = new Date();
    ordered().forEach(function (tz) {
      var lab = label(tz), isP = tz === primary;
      var tr = el('tr', isP ? 'tc-primary' : '');
      var c1 = el('td'); c1.appendChild(el('strong', '', lab.city)); c1.appendChild(el('div', 'tc-sub', (lab.country ? lab.country + ' · ' : '') + gmt(tz, now) + ' · ' + tz));
      var c2 = el('td', 'tc-now'); nowCells.push([c2, tz]);
      var c3 = el('td', 'tc-eq');
      if (t && dt) {
        var tp = t.split(':'), dp = dt.split('-');
        var utc = toUtc(+dp[0], +dp[1] - 1, +dp[2], +tp[0], +tp[1], primary);
        var diff = Math.round((Date.parse(ymd(utc, tz)) - Date.parse(ymd(utc, primary))) / 864e5);
        c3.textContent = fmtTime(utc, tz) + ' · ' + fmtDate(utc, tz) + (diff ? (diff > 0 ? ' (+' + diff + ' day)' : ' (' + diff + ' day)') : '');
      } else c3.textContent = '—';
      var c4 = el('td', 'tc-actions');
      var star = el('button', 'tc-btn' + (isP ? ' on' : ''), isP ? '★' : '☆');
      star.type = 'button'; star.title = isP ? 'Primary timezone' : 'Set as primary'; star.setAttribute('aria-label', star.title + ': ' + lab.city);
      star.addEventListener('click', function () { primary = tz; if (zones.indexOf(tz) < 0) zones.unshift(tz); render(); });
      c4.appendChild(star);
      if (!isP) {
        var rm = el('button', 'tc-btn', '✕'); rm.type = 'button'; rm.title = 'Remove'; rm.setAttribute('aria-label', 'Remove ' + lab.city);
        rm.addEventListener('click', function () { zones = zones.filter(function (z) { return z !== tz; }); render(); });
        c4.appendChild(rm);
      }
      [c1, c2, c3, c4].forEach(function (c) { tr.appendChild(c); });
      body.appendChild(tr);
    });
    tick();
  }
  function tick() {
    var n = new Date();
    nowCells.forEach(function (p) { p[0].textContent = fmtTime(n, p[1]) + ' · ' + fmtDate(n, p[1]); });
  }

  // ---- search ----
  function search() {
    var q = $('tc-search').value.trim().toLowerCase(), box = $('tc-results'); box.textContent = '';
    if (!q) { box.hidden = true; return; }
    var hits = all.filter(function (z) { return z.city.toLowerCase().indexOf(q) > -1 || z.country.toLowerCase().indexOf(q) > -1 || z.value.toLowerCase().indexOf(q) > -1; }).slice(0, 30);
    if (!hits.length) { box.appendChild(el('div', 'tc-empty', 'No matching city or country')); box.hidden = false; return; }
    var n = new Date();
    hits.forEach(function (z) {
      var b = el('button', 'tc-hit'); b.type = 'button';
      b.appendChild(el('strong', '', z.city)); b.appendChild(el('span', '', ' ' + z.country + ' · ' + gmt(z.value, n)));
      b.addEventListener('click', function () { add(z.value); });
      box.appendChild(b);
    });
    box.hidden = false;
  }
  function add(tz) {
    if (zones.indexOf(tz) < 0 && tz !== primary) zones.push(tz);
    $('tc-search').value = ''; $('tc-results').hidden = true; render();
  }

  // ---- boot ----
  $('tc-date').value = ymd(new Date(), primary);
  $('tc-time').addEventListener('input', render);
  $('tc-date').addEventListener('input', render);
  $('tc-search').addEventListener('input', search);
  $('tc-search').addEventListener('keydown', function (e) { if (e.key === 'Enter') { var f = $('tc-results').querySelector('.tc-hit'); if (f) f.click(); } });
  $('tc-now-btn').addEventListener('click', function () {
    var n = new Date(); $('tc-date').value = ymd(n, primary);
    var v = parts(n.getTime(), primary); $('tc-time').value = String(v.hour).padStart(2, '0') + ':' + String(v.minute).padStart(2, '0'); render();
  });
  render();
  setInterval(tick, 1000);

  fetch('/data/timezones.json').then(function (r) { return r.json(); }).then(function (data) {
    all = data; data.forEach(function (z) { info[z.value] = z; }); render();
  }).catch(function () { /* table still works with raw IANA names */ });
})();
